"""A ledger of samples."""


class SampleLedger:
    def __init__(self, samples=()):
        self._samples = list(samples)

    def samples(self):
        """Return the samples held (a copy, so callers cannot change the ledger)."""
        return list(self._samples)

    def add(self, sample):
        """Add one sample to the ledger."""
        self.samples().append(sample)

    def total(self):
        """Return the total dose of the samples held."""
        return sum(x.dose for x in self._samples)


def describe_sample(sample):
    """Return a one-line description of a sample."""
    return "%s: %s" % (sample.batch, sample.dose)


def group_by_batch(samples):
    """Return a dict from batch to the list of samples with that batch."""
    groups = {}
    for x in samples:
        groups.setdefault(x.batch, []).append(x)
    return groups

